function parse_nested_parens(paren_string) {
  return paren_string.split(' ').map(group => {
    let maxDepth = 0;
    let currentDepth = 0;
    for (let char of group) {
      if (char === '(') {
        currentDepth++;
        maxDepth = Math.max(maxDepth, currentDepth);
      } else if (char === ')') {
        currentDepth--;
      }
    }
    return maxDepth;
  });
}

